using System.Collections.Frozen;

namespace CatalogSvc;

/// <summary>
/// Read-optimized product catalog. Call <see cref="Build"/> after loading
/// products to freeze the dictionaries and build the reverse category index.
/// </summary>
public class ProductCatalog
{
    private readonly Dictionary<string, string> _categories = new(StringComparer.OrdinalIgnoreCase);
    private readonly Dictionary<string, decimal> _prices = new(StringComparer.OrdinalIgnoreCase);

    private FrozenDictionary<string, string>? _frozenCategories;
    private FrozenDictionary<string, decimal>? _frozenPrices;
    // Reverse index: category → product codes (eliminates O(n) scan)
    private FrozenDictionary<string, string[]>? _productsByCategory;

    public void AddProduct(string code, string category, decimal price)
    {
        _categories[code] = category;
        _prices[code] = price;
        // Invalidate frozen views so Build() must be called again
        _frozenCategories = null;
        _frozenPrices = null;
        _productsByCategory = null;
    }

    /// <summary>
    /// Freezes the internal dictionaries and builds the reverse category index.
    /// Call once after all products have been added.
    /// </summary>
    public void Build()
    {
        _frozenCategories = _categories.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);
        _frozenPrices = _prices.ToFrozenDictionary(StringComparer.OrdinalIgnoreCase);

        _productsByCategory = _categories
            .GroupBy(kvp => kvp.Value, StringComparer.OrdinalIgnoreCase)
            .ToFrozenDictionary(
                g => g.Key,
                g => g.Select(kvp => kvp.Key).ToArray(),
                StringComparer.OrdinalIgnoreCase);
    }

    public string? GetCategory(string code)
    {
        var cats = _frozenCategories ?? (IReadOnlyDictionary<string, string>)_categories;
        return cats.TryGetValue(code, out var cat) ? cat : null;
    }

    public decimal GetTotalPrice(IEnumerable<string> codes)
    {
        var prices = _frozenPrices ?? (IReadOnlyDictionary<string, decimal>)_prices;
        decimal total = 0m;
        foreach (var code in codes)
        {
            if (prices.TryGetValue(code, out var price))
                total += price;
        }
        return total;
    }

    public List<string> GetProductsByCategory(string category)
    {
        // O(1) lookup via reverse index when built, O(n) fallback otherwise
        if (_productsByCategory is not null)
        {
            return _productsByCategory.TryGetValue(category, out var codes)
                ? new List<string>(codes)
                : [];
        }

        var result = new List<string>();
        foreach (var kvp in _categories)
        {
            if (kvp.Value.Equals(category, StringComparison.OrdinalIgnoreCase))
                result.Add(kvp.Key);
        }
        return result;
    }
}

